var maxSubarrayLength = function(nums) {
    const d = new Map();
    for (let i = 0; i < nums.length; i++) {
        if (!d.has(nums[i])) d.set(nums[i], []);
        d.get(nums[i]).push(i);
    }
    const sortedKeys = Array.from(d.keys()).sort((a, b) => b - a);
    let ans = 0, k = Infinity;
    for (const x of sortedKeys) {
        const idx = d.get(x);
        ans = Math.max(ans, idx[idx.length - 1] - k + 1);
        k = Math.min(k, idx[0]);
    }
    return ans;
};
